import { FC, HTMLAttributes, ReactNode, useCallback, useEffect, useMemo, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useNavigate } from 'react-router-dom';

import {
	Alert,
	Button,
	Checkbox,
	Flex,
	Form,
	Input,
	notification,
	Radio,
	Select,
	Table,
	TableColumnsType,
	Tooltip,
	Typography,
} from 'antd';
import { Formik } from 'formik';
import * as Yup from 'yup';

import AngleIcon from 'assets/images/icons/angle-down.svg?react';
import {
	EPostbackMethods,
	EpostbackParams,
	EPostbackStatuses,
	getParam,
	IPostback,
	IPostbackForm,
	PostbackLink,
	prepareCreateData,
	TParamNames,
	useAddPostbackMutation,
	useTestPostbackMutation,
	useUpdatePostbackMutation,
} from 'entities/Postback';
import { usePostbackSlice } from 'entities/Postback/hooks/usePostbackSlice';
import { useFilters } from 'features/Filters';
import { urlValidator } from 'shared/consts';
import { useMedia, useTrans } from 'shared/hooks';
import { EMainRoutes, EYmEvents, EYmEventsO1, EYmEventsO2 } from 'shared/typings';
import { ButtonStyleLink } from 'shared/ui';
import { replaceUrlWithHttps, sendYmEvent } from 'shared/utils';

import styles from './CreatePostbackForm.module.scss';

interface ICreatePostbackFormProps extends HTMLAttributes<HTMLDivElement> {
	postback?: IPostback;
}

export const CreatePostbackForm: FC<ICreatePostbackFormProps> = ({ className, postback, ...props }) => {
	const { t } = useTranslation();
	const navigate = useNavigate();
	const { postbackParams } = useTrans();

	const { sourcesOptions, offersOptions } = useFilters();
	const { values, setValues } = usePostbackSlice();

	const initialValues = useMemo(
		() => ({
			...values,
			...Object.keys(EpostbackParams).reduce(
				(acc, key) => {
					const value = EpostbackParams[key as keyof typeof EpostbackParams];

					return {
						...acc,
						[`${value}` as keyof TParamNames]: values[value] || `{${value}}`,
						[`${value}_name` as keyof TParamNames]: value,
					};
				},
				{} as Record<keyof TParamNames, string>,
			),
		}),
		[postback?.uuid], // eslint-disable-line
	);

	const [addPostback, { data, isLoading, isSuccess }] = useAddPostbackMutation();
	const [updatePostback, { isLoading: isEditLoading, isSuccess: isEditSuccess }] = useUpdatePostbackMutation();
	const [testPostback, { isLoading: isTestLoading, isSuccess: isTestSuccess, error: testError }] =
		useTestPostbackMutation();

	const isFormLoading = isLoading || isEditLoading || isTestLoading;

	const validations: Partial<Record<keyof IPostbackForm, Yup.AnySchema>> = {
		url: Yup.string()
			.required(t('Это поле обязательно для заполнения'))
			.matches(
				urlValidator,
				t(
					'Недопустимая ссылка. Проверьте ее формат и наличие недопустимых символов. Допустимые символы: a-z, A-Z, 0-9, -, ., _ и ~.',
				),
			)
			.max(4096, t('Количество символов не должно превышать {{characters}}', { characters: 4096 }))
			.transform((value) => (!value.startsWith(initialValues.protocol) ? `${initialValues.protocol}${value}` : value)),
		action_statuses: Yup.array().min(1, t('Это поле обязательно для заполнения')),
	};

	const params = [
		...Object.keys(postbackParams),
		...(postback?.data ? Object.keys(postback.data).filter((key) => !postbackParams[key as EpostbackParams]) : []),
	].sort(
		(a, b) => initialValues.params.indexOf(b as EpostbackParams) - initialValues.params.indexOf(a as EpostbackParams),
	);

	params.forEach((param) => {
		validations[`${param}_name` as keyof IPostbackForm] = Yup.string().when('params', (params: string[][], schema) =>
			params[0].includes(param)
				? schema.matches(/^[a-zA-Z0-9-._~]*$/, 'Допустимые символы: a-z, A-Z, 0-9, -, ., _, и ~')
				: schema,
		);
	});

	const validationSchema = Yup.object(validations);

	useEffect(() => {
		if (isSuccess) {
			sendYmEvent({
				event: EYmEvents.SEND_ADD_POSTBACK_SUCCESS,
				o1: [EYmEventsO1.ACCOUNT, EYmEventsO1.PUBLISHER, EYmEventsO1.INSTRUMENTS],
				o2: [EYmEventsO2.POSTBACK, EYmEventsO2.ADD_POSTBACK],
				si: data.uuid,
				wi: data.source?.uuid,
			});

			navigate(`/${EMainRoutes.TOOLS}/${EMainRoutes.POSTBACKS}/${EMainRoutes.EDIT}/${data.uuid}`);
			notification.open({
				message: t('Сохранено'),
				type: 'success',
				placement: 'topRight',
				showProgress: true,
				pauseOnHover: true,
			});
		}
	}, [isSuccess]); // eslint-disable-line

	useEffect(() => {
		if (isEditSuccess) {
			notification.open({
				message: t('Сохранено'),
				type: 'success',
				placement: 'topRight',
				showProgress: true,
				pauseOnHover: true,
			});
			setTestIsDisabled(false);
		}
	}, [isEditSuccess]); // eslint-disable-line

	const onBeforeUnload = useCallback(
		(e: BeforeUnloadEvent) => {
			if (initialValues.url || initialValues.url) {
				e.preventDefault();
				return '';
			}
		},
		[initialValues],
	);

	useEffect(() => {
		window.addEventListener('beforeunload', onBeforeUnload);

		return () => {
			window.removeEventListener('beforeunload', onBeforeUnload);
		};
	}, [initialValues, onBeforeUnload]);

	interface DataType {
		key: React.Key;
		checkbox: ReactNode;
		name: ReactNode;
		input: ReactNode;
		equal: ReactNode;
		type: ReactNode;
	}

	const columns: TableColumnsType<DataType> = [
		{
			dataIndex: 'checkbox',
			key: 'checkbox',
		},
		{
			title: t('Параметр'),
			dataIndex: 'name',
			key: 'name',
		},
		{
			title: t('Имя параметра'),
			dataIndex: 'input',
			key: 'input',
			width: 200,
		},
		{
			title: '=',
			dataIndex: 'equal',
			key: 'equal',
		},
		{
			title: t('Значение'),
			dataIndex: 'type',
			key: 'type',
			width: 200,
		},
	];

	const [showAllParams, setShowAllParams] = useState(false);
	const isMd = useMedia();
	const [testIsDisabled, setTestIsDisabled] = useState(!!postback?.uuid);

	return (
		<Formik
			initialValues={initialValues}
			enableReinitialize
			validationSchema={validationSchema}
			onSubmit={(values) => {
				postback?.uuid
					? updatePostback({ ...prepareCreateData(values), uuid: postback.uuid })
					: addPostback(prepareCreateData(values));
			}}>
			{({ values, errors, touched, handleChange, handleBlur, handleSubmit, setFieldValue }) => {
				return (
					<form onSubmit={handleSubmit} onChange={() => setTestIsDisabled(true)}>
						<Flex {...props} vertical gap={32} className={className}>
							<Flex gap={12} vertical={isMd}>
								<Typography.Text strong style={{ minWidth: 160 }}>
									{t('Тип события')}
								</Typography.Text>
								<Typography.Text>{t('Изменение статуса действий')}</Typography.Text>
							</Flex>
							<Flex vertical gap={16}>
								<Typography.Title level={4} style={{ margin: 0 }}>
									1. {t('Настройте ссылку')}
								</Typography.Title>

								<Form.Item
									className={styles.formItem}
									label={t('Выберите площадку и оффер')}
									validateStatus={errors.source && touched.source ? 'error' : ''}
									help={errors.source && touched.source && errors.source}>
									<Flex vertical={isMd} gap={12}>
										<Select
											options={sourcesOptions}
											onChange={(e) => {
												setValues({ ...initialValues, source: e });
												setFieldValue('source', e);
											}}
											onBlur={handleBlur}
											value={values.source}
											showSearch
											optionFilterProp="label"
											placeholder={t('Выбрать площадку')}
											allowClear
											disabled={isFormLoading}
										/>
										<Select
											options={offersOptions}
											onChange={(e) => {
												setValues({ ...initialValues, offer: e });
												setFieldValue('offer', e);
											}}
											onBlur={handleBlur}
											value={values.offer}
											showSearch
											optionFilterProp="label"
											placeholder={t('Выбрать оффер')}
											allowClear
											disabled={isFormLoading}
										/>
									</Flex>
								</Form.Item>

								<Form.Item
									className={styles.formItem}
									label={t('Тип запроса')}
									tooltip={t('Метод GET передаёт параметры в хвосте URL, а POST - в теле запроса.')}
									validateStatus={errors.method && touched.method ? 'error' : ''}
									help={errors.method && touched.method && errors.method}
									required>
									<Radio.Group
										name="method"
										onChange={(e) => {
											setValues({ ...values, method: e.target.value });
											handleChange(e);
										}}
										onBlur={handleBlur}
										value={values.method}
										disabled={isFormLoading}>
										<Radio key={EPostbackMethods.GET} value={EPostbackMethods.GET}>
											GET
										</Radio>
										<Radio key={EPostbackMethods.POST} value={EPostbackMethods.POST}>
											POST
										</Radio>
									</Radio.Group>
								</Form.Item>

								<Form.Item
									className={styles.formItem}
									label={t('Статус действия')}
									tooltip={t('Берётся из статистики по действиям.')}
									validateStatus={errors.action_statuses && touched.action_statuses ? 'error' : ''}
									help={errors.action_statuses && touched.action_statuses && errors.action_statuses}
									required>
									<Checkbox.Group
										name="action_statuses"
										onChange={(v) => {
											setValues({ ...values, action_statuses: v });
											setFieldValue('action_statuses', v);
										}}
										value={values.action_statuses}
										disabled={isFormLoading}
										style={{ gap: '8px' }}>
										<Checkbox key={EPostbackStatuses.PENDING} value={EPostbackStatuses.PENDING}>
											{t('Открытый')}
										</Checkbox>
										<Checkbox key={EPostbackStatuses.APPROVED} value={EPostbackStatuses.APPROVED}>
											{t('Подтвержденный')}
										</Checkbox>
										<Checkbox key={EPostbackStatuses.REJECTED} value={EPostbackStatuses.REJECTED}>
											{t('Отклоненный')}
										</Checkbox>
									</Checkbox.Group>
								</Form.Item>

								<Form.Item
									className={styles.formItemVertical}
									layout="vertical"
									label={t('Ссылка на сервер, по которой будет приходить HTTP-запрос')}
									required
									validateStatus={errors.url && touched.url ? 'error' : ''}
									help={errors.url && touched.url && errors.url}>
									<Input
										name="url"
										placeholder="Укажите URL"
										addonBefore={
											<Select
												value={values.protocol}
												onChange={(v) => {
													setValues({ ...initialValues, protocol: v });
													setFieldValue('protocol', v);
												}}>
												<Select.Option value="https://">https://</Select.Option>
												<Select.Option value="http://">http://</Select.Option>
											</Select>
										}
										onChange={(e) => {
											const { url, protocol } = replaceUrlWithHttps(e.target.value);
											setFieldValue('url', url).then(() => {
												setValues({ ...values, url, protocol: protocol || values.protocol });
												protocol && setFieldValue('protocol', protocol);
											});
										}}
										onBlur={handleBlur}
										value={values.url}
										disabled={isFormLoading}
									/>
								</Form.Item>
							</Flex>
							<Flex vertical gap={16}>
								<Typography.Title level={4} style={{ margin: 0 }}>
									2. {t('Задайте параметры')}
								</Typography.Title>

								<Checkbox.Group
									name="params"
									onChange={(v) => {
										setValues({ ...values, params: v });
										setFieldValue('params', v);
									}}
									value={values.params}
									disabled={isFormLoading}>
									<Table<DataType>
										style={{ width: '100%' }}
										columns={columns}
										dataSource={params.map((key) =>
											getParam(
												key as EpostbackParams,
												postbackParams[key as EpostbackParams],
												values,
												setValues,
												handleChange,
												initialValues,
												errors,
												touched,
												handleBlur,
												isFormLoading,
											),
										)}
										bordered={false}
										scroll={isMd ? { x: 'max-content' } : undefined}
										pagination={false}
										showSorterTooltip={false}
										onRow={(_, index) => {
											return { className: !showAllParams && index && index >= 5 ? styles.hidden : undefined };
										}}
									/>
								</Checkbox.Group>

								<Button
									type="link"
									icon={<AngleIcon transform={showAllParams ? 'rotate(180)' : undefined} />}
									iconPosition="end"
									onClick={() => setShowAllParams(!showAllParams)}>
									{showAllParams ? t('Свернуть параметры') : t('Показать больше параметров')}
								</Button>
							</Flex>
							<Flex vertical align="start" gap={16}>
								<Typography.Title level={4} style={{ margin: 0 }}>
									3. {t('Скопируйте ссылку')}
								</Typography.Title>

								<PostbackLink data={values} errors={errors} />

								<Flex vertical={isMd} style={{ width: '100%' }} gap={16} align="center">
									<Tooltip title={testIsDisabled ? t('Для тестирования Postback его необходимо сохранить') : undefined}>
										<Button
											disabled={isFormLoading || testIsDisabled}
											onClick={() => {
												testPostback(postback?.uuid || '');
											}}
											block={isMd}
											loading={isTestLoading}>
											{t('Тестировать код')}
										</Button>
									</Tooltip>

									{isTestLoading && (
										<Typography.Text type="secondary">{t('Тест обычно занимает 5 секунд')}</Typography.Text>
									)}

									{isTestSuccess && <Alert message={t('Тест прошел успешно!')} type="success" showIcon closable />}

									{testError && (
										<Alert
											message={t(
												'Тест не пройден. Это произошло по разным причинам: конечная точка не ответила, домен не зарегистрирован, конечная точка долго обрабатывала запрос или просто на странице возникла ошибка. Попробуйте еще раз позже',
											)}
											type="error"
											showIcon
											closable
										/>
									)}
								</Flex>
							</Flex>
							<Flex justify="space-between" gap={16}>
								<ButtonStyleLink disabled={isFormLoading} to={`/${EMainRoutes.TOOLS}/${EMainRoutes.POSTBACKS}`}>
									{t('Отменить')}
								</ButtonStyleLink>

								<Button
									type="primary"
									htmlType="submit"
									loading={isFormLoading && !isTestLoading}
									disabled={isFormLoading || !!Object.keys(errors).length || !values.url}>
									{t('Сохранить')}
								</Button>
							</Flex>
						</Flex>
					</form>
				);
			}}
		</Formik>
	);
};
