import { FC } from 'react';

import { Card, Flex, FlexProps, Tag, theme, Typography } from 'antd';
import cn from 'classnames';
import { FormikErrors } from 'formik';

import { IPostbackForm } from 'entities/Postback/model/types';
import { useMedia } from 'shared/hooks';
import { CopyButton } from 'shared/ui';

import styles from './PostbackLink.module.scss';

interface IPostbackLinkProps extends Omit<FlexProps, 'children'> {
	data: IPostbackForm;
	errors: FormikErrors<IPostbackForm>;
}

export const PostbackLink: FC<IPostbackLinkProps> = ({ className, data, errors, ...props }) => {
	const isMd = useMedia();
	const {
		token: { colorBorder, colorFillTertiary },
	} = theme.useToken();

	const isDisabled = !data.url || !!errors.url;

	const createURL = () => {
		try {
			const url = new URL(data.protocol + data.url);

			data.params.forEach((param) => {
				url.searchParams.set(data[`${param}_name`] || param, data[param] || `{${param}}`);
			});

			return decodeURI(url.toString());
		} catch (e) {
			return '';
		}
	};

	return (
		<Card className={cn(className, styles.postbackLink)} styles={{ body: { padding: isMd ? 16 : 24 } }}>
			<Flex {...props} vertical={isMd} gap={8}>
				<Flex gap={4} className={styles.link} style={{ borderColor: colorBorder, backgroundColor: colorFillTertiary }}>
					{!isDisabled && (
						<>
							{data.protocol}
							{data.url}
							{!data.url.endsWith('/') && '/'}
							{data.params.map((param, i) => {
								return (
									<Tag style={{ margin: 0 }}>
										<Typography.Text
											type="secondary"
											style={{
												fontSize: 12,
											}}>
											{i === 0 ? '?' : '&'}
											{`${data[`${param}_name`] || param}=${data[param] || `{${param}}`}`}
										</Typography.Text>
									</Tag>
								);
							})}
						</>
					)}
					{isDisabled && <Typography.Text type="secondary">https://website.com/targetpage/</Typography.Text>}
				</Flex>
				<CopyButton text={createURL()} disabled={isDisabled} textMode type="primary" />
			</Flex>
		</Card>
	);
};
