import { replaceUrlWithHttps } from 'shared/utils';

import { EpostbackParams, IPostback, IPostbackForm, TCreatePostbackRequest } from '../model/types';

export const prepareCreateData = (values: IPostbackForm): TCreatePostbackRequest => {
	const additionalData = values.params.reduce(
		(acc, param) => {
			return {
				...acc,
				[values[`${param}_name`] || param]: values[param] || `{${param}}`,
			};
		},
		{} as Record<EpostbackParams, string>,
	);

	return {
		source: values.source || null,
		offer: values.offer || null,
		action_statuses: values.action_statuses,
		method: values.method,
		url: values.protocol + values.url,
		data: additionalData,
	};
};

export const preparePostbackData = (data: IPostback): IPostbackForm => {
	const { url, protocol } = replaceUrlWithHttps(data.url);

	const formData: IPostbackForm = {
		source: data?.source?.uuid,
		offer: data?.offer?.uuid,
		action_statuses: data.action_statuses,
		method: data.method,
		protocol: protocol || 'https://',
		url,
		params: [],
	};

	if (data.data) {
		Object.keys(data.data).forEach((key) => {
			formData.params.push(key as EpostbackParams);
			formData[key as EpostbackParams] = data.data ? data.data[key as EpostbackParams] : undefined;
			formData[`${key}_name` as EpostbackParams] = data.data ? key : undefined;
		});
	}

	return formData;
};
