import { FocusEventHandler } from 'react';

import { Checkbox, Form, Input } from 'antd';
import { FormikErrors, FormikTouched } from 'formik';

import { EpostbackParams, IPostbackForm, TParamNames } from '../model/types';

export const getParam = (
	param: EpostbackParams,
	name: string,
	values: IPostbackForm,
	setValues: (values: IPostbackForm) => void,
	handleChange: (e: React.ChangeEvent<unknown>) => void,
	initialValues: IPostbackForm,
	errors: FormikErrors<IPostbackForm>,
	touched: FormikTouched<IPostbackForm>,
	onBlur: FocusEventHandler<HTMLInputElement>,
	isLoading: boolean,
) => {
	const paramName: keyof TParamNames = `${param}_name`;
	return {
		key: param,
		checkbox: <Checkbox key={param} value={param} />,
		name: name,
		input: values.params.includes(param) ? (
			<Form.Item
				validateStatus={errors[paramName] && touched[paramName] ? 'error' : ''}
				help={errors[paramName] && touched[paramName] && errors[paramName]}>
				<Input
					name={paramName}
					onChange={(e) => {
						setValues({ ...initialValues, [paramName]: e.target.value });
						handleChange(e);
					}}
					onBlur={onBlur}
					value={values[paramName]}
					placeholder={param}
					disabled={isLoading}
				/>
			</Form.Item>
		) : (
			param
		),
		equal: '=',
		type: values.params.includes(param) && (
			<Form.Item
				validateStatus={errors[param] && touched[param] ? 'error' : ''}
				help={errors[param] && touched[param] && errors[param]}>
				<Input
					name={param}
					onChange={(e) => {
						setValues({ ...initialValues, [param]: e.target.value });
						handleChange(e);
					}}
					onBlur={onBlur}
					value={values[param]}
					placeholder={`{${param}}`}
					disabled={isLoading}
				/>
			</Form.Item>
		),
	};
};
