import { useDispatch, useSelector } from 'react-redux';

import { RootState } from 'app/appStore';
import { clearValues, IPostbackForm, setValues } from 'entities/Postback';

export const usePostbackSlice = () => {
	const dispatch = useDispatch();

	return {
		...useSelector((s: RootState) => s.postbackSlice),
		setValues: (values: IPostbackForm) => dispatch(setValues(values)),
		clearValues: () => dispatch(clearValues()),
	};
};
